    <script defer src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js" integrity="sha384-+VBxd3r6XgURycqtZ117nYw44OOcIax56Z4dCRWbxyPt0Koah1uHoK0o4+/RRE05" crossorigin="anonymous" onload="renderMathInElement(document.body);"></script>

    <script>
        // ==========================================================
        // DATA SOURCE (Simulating Parsed Content)
        // ==========================================================
        const courseData = [
            {
                type: 'text',
                title: 'Introduction',
                icon: '<path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/>', // Info icon
                content: `
                    <p>Simple Harmonic Motion (SHM) is a fundamental concept in physics describing a type of periodic motion where the <span class="highlight-term">restoring force</span> is directly proportional to the displacement and acts in the direction opposite to that of displacement.</p>
                    <p>Think of a swinging pendulum or a vibrating guitar string. These systems oscillate back and forth through an equilibrium position.</p>
                `
            },
            {
                type: 'formula',
                title: 'Defining Equation (Hooke\'s Law)',
                id: 'f_hooke',
                formula: 'F = -kx',
                explanation: 'This is the fundamental condition for Simple Harmonic Motion. The negative sign indicates that the force is a restoring force, meaning it always tries to bring the object back to the equilibrium position ($x=0$).',
                variables: [
                    { symbol: 'F', meaning: 'Restoring Force (Newtons)' },
                    { symbol: 'k', meaning: 'Spring Constant (N/m)' },
                    { symbol: 'x', meaning: 'Displacement from equilibrium (m)' }
                ]
            },
            {
                type: 'text',
                title: 'Key Characteristics',
