                header.innerHTML += `<div class="card-title">${section.title}</div>`;
                card.appendChild(header);

                // Body
                const body = document.createElement('div');
                body.className = 'card-body';

                if (section.type === 'text') {
                    body.innerHTML = section.content;
                } 
                else if (section.type === 'formula') {
                    card.classList.add('formula-card');
                    // Math container
                    const mathDiv = document.createElement('div');
                    mathDiv.className = 'formula-display';
                    mathDiv.innerHTML = `$$${section.formula}$$`;

                    // Action Buttons
                    const actions = document.createElement('div');
                    actions.className = 'formula-actions';

                    // Explain Button
                    const explainBtn = document.createElement('button');
                    explainBtn.className = 'btn btn-outline';
                    explainBtn.innerHTML = 'Explain Formula';
                    explainBtn.onclick = () => toggleFormulaDetails(section.id);

                    // Lab Button
                    const labBtn = document.createElement('button');
                    labBtn.className = 'btn btn-primary';
                    labBtn.innerHTML = 'Open Formula Lab';
                    labBtn.onclick = () => openLab();

                    actions.appendChild(explainBtn);
                    actions.appendChild(labBtn);

                    // Details Panel (Hidden by default)
                    const details = document.createElement('div');
                    details.className = 'formula-details';
                    details.id = `details-${section.id}`;

                    let varsHtml = section.variables.map(v => 
                        `<li class="variable-item"><span class="variable-symbol">${v.symbol}</span>: ${v.meaning}</li>`
                    ).join('');

                    details.innerHTML = `
